  /// A flat list of all available icon names.
  static final List<String> allIcons = categorizedIcons.values
      .expand((list) => list)
      .toList();

  /// Gets the full asset path for a given icon name.
  static String getPath(String iconName) {
    // If the iconName is one of the old hardcoded icons, map it to a suitable SVG fallback
    String mappedName = iconName;
    switch (iconName) {
      case 'hotel':
        mappedName = allIcons.contains('hotel') ? 'hotel' : 'bed';
        break;
      case 'parking':
        mappedName = allIcons.contains('parking') ? 'parking' : 'car';
        break;
      case 'wifi':
        mappedName = allIcons.contains('wifi') ? 'wifi' : 'radioWaves';
        break;
      case 'lock':
        mappedName = allIcons.contains('lock') ? 'lock' : 'lock-locked';
        break;
      case 'seat':
        mappedName = allIcons.contains('seat') ? 'seat' : 'ticket';
        break;
      case 'code':
        mappedName = allIcons.contains('code') ? 'code' : 'qr-code';
        break;
      case 'note':
        mappedName = allIcons.contains('note') ? 'note' : 'stickyNote';
        break;
    }

    // Check if the mapped name is in the list, otherwise default to a fallback
    if (!allIcons.contains(mappedName)) {
      if (allIcons.contains('note')) {
        mappedName = 'note';
      } else if (allIcons.contains('stickyNote')) {
        mappedName = 'stickyNote';
      } else if (allIcons.isNotEmpty) {
        mappedName = allIcons.first;
      } else {
        return '';
      }
    }

    return '$basePath/$mappedName.svg';
  }

  /// Returns the asset path for a **line** (outline) icon.
  /// Used for UI chrome elements: settings gear, search, FAB plus-circle,
  /// copy, close (x), checkmark, star, inbox, etc.
  static String getLinePath(String name) => '$lineBasePath/$name.svg';

  static const String solidBasePath = 'assets/icons/solid';
  static String getSolidPath(String name) => '$solidBasePath/$name.svg';
}
